-- Generated relational module tables. Changes belong in a new migration after deployment.
CREATE TABLE visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,customer_id uuid NOT NULL,representative_id uuid NOT NULL,area_id uuid,date date NOT NULL DEFAULT CURRENT_DATE,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','reviewed','approved','rejected','confirmed','cancelled','completed')),notes text,details jsonb NOT NULL DEFAULT '{}',visit_type text NOT NULL DEFAULT 'routine',purpose text,outcome text,next_action text,follow_up date,check_in timestamptz,check_out timestamptz,latitude numeric(10,7),longitude numeric(10,7),CHECK(check_out IS NULL OR check_in IS NULL OR check_out>=check_in),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id),FOREIGN KEY(company_id,representative_id) REFERENCES users(company_id,id),FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
CREATE INDEX visits_rep_date_idx ON visits(company_id,representative_id,date);
CREATE INDEX visits_customer_date_idx ON visits(company_id,customer_id,date);
ALTER TABLE visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY visits_read ON visits FOR SELECT USING(company_id=app_company() AND (app_scope('visits',representative_id,area_id) ));
CREATE POLICY visits_insert ON visits FOR INSERT WITH CHECK(company_id=app_company() AND representative_id=app_user() AND app_can('visits.create') AND (area_id IS NULL OR app_area(area_id)));
CREATE POLICY visits_update ON visits FOR UPDATE USING(company_id=app_company() AND ((representative_id=app_user() AND status='draft' AND app_can('visits.create')) OR (app_can('visits.approve') AND (area_id IS NULL OR app_area(area_id))))) WITH CHECK(company_id=app_company());
CREATE TABLE collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,customer_id uuid NOT NULL,representative_id uuid NOT NULL,area_id uuid,date date NOT NULL DEFAULT CURRENT_DATE,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','reviewed','approved','rejected','confirmed','cancelled','completed')),notes text,details jsonb NOT NULL DEFAULT '{}',amount numeric(16,2) NOT NULL CHECK(amount>0),currency text NOT NULL DEFAULT 'EGP',payment_method text NOT NULL CHECK(payment_method IN ('cash','cheque','bank_transfer','instapay','wallet','card','other')),reference text,client_transaction_id uuid NOT NULL,confirmed_by uuid,confirmed_at timestamptz,UNIQUE(company_id,client_transaction_id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id),FOREIGN KEY(company_id,representative_id) REFERENCES users(company_id,id),FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
CREATE INDEX collections_rep_date_idx ON collections(company_id,representative_id,date);
CREATE INDEX collections_customer_date_idx ON collections(company_id,customer_id,date);
ALTER TABLE collections ENABLE ROW LEVEL SECURITY;
CREATE POLICY collections_read ON collections FOR SELECT USING(company_id=app_company() AND (app_scope('collections',representative_id,area_id) ));
CREATE POLICY collections_insert ON collections FOR INSERT WITH CHECK(company_id=app_company() AND representative_id=app_user() AND app_can('collections.create') AND (area_id IS NULL OR app_area(area_id)));
CREATE POLICY collections_update ON collections FOR UPDATE USING(company_id=app_company() AND ((representative_id=app_user() AND status='draft' AND app_can('collections.create')) OR (app_can('collections.approve') AND (area_id IS NULL OR app_area(area_id))))) WITH CHECK(company_id=app_company());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,customer_id uuid NOT NULL,representative_id uuid NOT NULL,area_id uuid,date date NOT NULL DEFAULT CURRENT_DATE,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','reviewed','approved','rejected','confirmed','cancelled','completed')),notes text,details jsonb NOT NULL DEFAULT '{}',amount numeric(16,2) NOT NULL CHECK(amount>=0),currency text NOT NULL DEFAULT 'EGP',reference text NOT NULL,UNIQUE(company_id,reference),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id),FOREIGN KEY(company_id,representative_id) REFERENCES users(company_id,id),FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
