CREATE INDEX invoices_customer_date_idx ON invoices(company_id,customer_id,date);
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoices_read ON invoices FOR SELECT USING(company_id=app_company() AND (app_scope('invoices',representative_id,area_id) OR (app_can('invoices.view_customer_history') AND app_area(area_id))));
CREATE POLICY invoices_insert ON invoices FOR INSERT WITH CHECK(company_id=app_company() AND representative_id=app_user() AND app_can('invoices.create') AND (area_id IS NULL OR app_area(area_id)));
CREATE POLICY invoices_update ON invoices FOR UPDATE USING(company_id=app_company() AND ((representative_id=app_user() AND status='draft' AND app_can('invoices.create')) OR (app_can('invoices.approve') AND (area_id IS NULL OR app_area(area_id))))) WITH CHECK(company_id=app_company());
CREATE TABLE plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,customer_id uuid ,representative_id uuid NOT NULL,area_id uuid,date date NOT NULL DEFAULT CURRENT_DATE,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','reviewed','approved','rejected','confirmed','cancelled','completed')),notes text,details jsonb NOT NULL DEFAULT '{}',title text NOT NULL,plan_type text NOT NULL CHECK(plan_type IN ('weekly','monthly','annual')),end_date date NOT NULL,visit_target int NOT NULL DEFAULT 0 CHECK(visit_target>=0),collection_target numeric(16,2) NOT NULL DEFAULT 0 CHECK(collection_target>=0),sales_target numeric(16,2) NOT NULL DEFAULT 0 CHECK(sales_target>=0),new_customer_target int NOT NULL DEFAULT 0 CHECK(new_customer_target>=0),CHECK(end_date>=date),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id),FOREIGN KEY(company_id,representative_id) REFERENCES users(company_id,id),FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
CREATE INDEX plans_rep_date_idx ON plans(company_id,representative_id,date);
CREATE INDEX plans_customer_date_idx ON plans(company_id,customer_id,date);
ALTER TABLE plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY plans_read ON plans FOR SELECT USING(company_id=app_company() AND (app_scope('plans',representative_id,area_id) ));
CREATE POLICY plans_insert ON plans FOR INSERT WITH CHECK(company_id=app_company() AND representative_id=app_user() AND app_can('plans.create') AND (area_id IS NULL OR app_area(area_id)));
CREATE POLICY plans_update ON plans FOR UPDATE USING(company_id=app_company() AND ((representative_id=app_user() AND status='draft' AND app_can('plans.create')) OR (app_can('plans.approve') AND (area_id IS NULL OR app_area(area_id))))) WITH CHECK(company_id=app_company());
CREATE TABLE leaves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,customer_id uuid ,representative_id uuid NOT NULL,area_id uuid,date date NOT NULL DEFAULT CURRENT_DATE,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','reviewed','approved','rejected','confirmed','cancelled','completed')),notes text,details jsonb NOT NULL DEFAULT '{}',leave_type_id uuid NOT NULL, end_date date NOT NULL,days numeric(6,2) NOT NULL CHECK(days>0),FOREIGN KEY(company_id,leave_type_id) REFERENCES leave_types(company_id,id),CHECK(end_date>=date),CHECK(extract(year from date)=extract(year from end_date)),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id),FOREIGN KEY(company_id,representative_id) REFERENCES users(company_id,id),FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
CREATE INDEX leaves_rep_date_idx ON leaves(company_id,representative_id,date);
CREATE INDEX leaves_customer_date_idx ON leaves(company_id,customer_id,date);
ALTER TABLE leaves ENABLE ROW LEVEL SECURITY;
CREATE POLICY leaves_read ON leaves FOR SELECT USING(company_id=app_company() AND (app_scope('leaves',representative_id,area_id) ));
CREATE POLICY leaves_insert ON leaves FOR INSERT WITH CHECK(company_id=app_company() AND representative_id=app_user() AND app_can('leaves.create') AND (area_id IS NULL OR app_area(area_id)));
CREATE POLICY leaves_update ON leaves FOR UPDATE USING(company_id=app_company() AND ((representative_id=app_user() AND status='draft' AND app_can('leaves.create')) OR (app_can('leaves.approve') AND (area_id IS NULL OR app_area(area_id))))) WITH CHECK(company_id=app_company());
CREATE TABLE plan_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,plan_id uuid NOT NULL,customer_id uuid NOT NULL,date date NOT NULL,activity text NOT NULL,FOREIGN KEY(company_id,plan_id) REFERENCES plans(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id));
ALTER TABLE companies ENABLE ROW LEVEL SECURITY;
CREATE POLICY companies_read ON companies FOR SELECT USING(id=app_company() AND (true));
CREATE POLICY companies_write ON companies FOR ALL USING(id=app_company() AND (app_can('settings.manage'))) WITH CHECK(id=app_company() AND (app_can('settings.manage')));
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE POLICY users_read ON users FOR SELECT USING(company_id=app_company() AND (id=app_user() OR app_can('users.view') OR EXISTS(SELECT 1 FROM user_areas ua WHERE ua.user_id=users.id AND app_area(ua.area_id))));
CREATE POLICY users_write ON users FOR ALL USING(company_id=app_company() AND (app_can('users.edit'))) WITH CHECK(company_id=app_company() AND (app_can('users.edit')));
