CREATE POLICY regions_write ON regions FOR ALL USING(company_id=app_company() AND (app_can('areas.manage'))) WITH CHECK(company_id=app_company() AND (app_can('areas.manage')));
ALTER TABLE areas ENABLE ROW LEVEL SECURITY;
