CREATE POLICY user_roles_read ON user_roles FOR SELECT USING(company_id=app_company() AND (true));
CREATE POLICY user_roles_write ON user_roles FOR ALL USING(company_id=app_company() AND (app_can('roles.manage'))) WITH CHECK(company_id=app_company() AND (app_can('roles.manage')));
ALTER TABLE customers ENABLE ROW LEVEL SECURITY;
