CREATE POLICY customers_write ON customers FOR ALL USING(company_id=app_company() AND (app_area(area_id) AND app_can('customers.edit'))) WITH CHECK(company_id=app_company() AND (app_area(area_id) AND app_can('customers.edit')));
ALTER TABLE customer_assignments ENABLE ROW LEVEL SECURITY;
