CREATE POLICY customer_assignments_write ON customer_assignments FOR ALL USING(company_id=app_company() AND (app_can('customers.edit'))) WITH CHECK(company_id=app_company() AND (app_can('customers.edit')));
ALTER TABLE leave_types ENABLE ROW LEVEL SECURITY;
CREATE POLICY leave_types_read ON leave_types FOR SELECT USING(company_id=app_company() AND (true));
CREATE POLICY leave_types_write ON leave_types FOR ALL USING(company_id=app_company() AND (app_can('settings.manage'))) WITH CHECK(company_id=app_company() AND (app_can('settings.manage')));
