CREATE POLICY leave_balances_read ON leave_balances FOR SELECT USING(company_id=app_company() AND (user_id=app_user() OR app_can('leaves.manage_balance') OR app_can('leaves.approve')));
CREATE POLICY leave_balances_write ON leave_balances FOR ALL USING(company_id=app_company() AND (app_can('leaves.manage_balance') OR app_can('leaves.approve'))) WITH CHECK(company_id=app_company() AND (app_can('leaves.manage_balance') OR app_can('leaves.approve')));
ALTER TABLE approval_workflows ENABLE ROW LEVEL SECURITY;
CREATE POLICY approval_workflows_read ON approval_workflows FOR SELECT USING(company_id=app_company() AND (true));
CREATE POLICY approval_workflows_write ON approval_workflows FOR ALL USING(company_id=app_company() AND (app_can('settings.manage'))) WITH CHECK(company_id=app_company() AND (app_can('settings.manage')));
ALTER TABLE approval_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY approval_requests_read ON approval_requests FOR SELECT USING(company_id=app_company() AND (submitted_by=app_user() OR (app_can(module||'.approve') AND (area_id IS NULL OR app_area(area_id)))));
CREATE POLICY approval_requests_write ON approval_requests FOR ALL USING(company_id=app_company() AND (submitted_by=app_user() OR (app_can(module||'.approve') AND (area_id IS NULL OR app_area(area_id))))) WITH CHECK(company_id=app_company() AND (submitted_by=app_user() OR (app_can(module||'.approve') AND (area_id IS NULL OR app_area(area_id)))));
ALTER TABLE approval_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY approval_actions_read ON approval_actions FOR SELECT USING(company_id=app_company() AND (EXISTS(SELECT 1 FROM approval_requests r WHERE r.id=request_id)));
CREATE POLICY approval_actions_write ON approval_actions FOR ALL USING(company_id=app_company() AND (approver_id=app_user() AND EXISTS(SELECT 1 FROM approval_requests r WHERE r.id=request_id AND app_can(r.module||'.approve')))) WITH CHECK(company_id=app_company() AND (approver_id=app_user() AND EXISTS(SELECT 1 FROM approval_requests r WHERE r.id=request_id AND app_can(r.module||'.approve'))));
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
