CREATE POLICY notifications_write ON notifications FOR ALL USING(company_id=app_company() AND (user_id=app_user())) WITH CHECK(company_id=app_company() AND (user_id=app_user()));
ALTER TABLE attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY attachments_read ON attachments FOR SELECT USING(company_id=app_company() AND (uploaded_by=app_user() OR app_can('customers.view')));
CREATE POLICY attachments_write ON attachments FOR ALL USING(company_id=app_company() AND (uploaded_by=app_user())) WITH CHECK(company_id=app_company() AND (uploaded_by=app_user()));
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_logs_read ON audit_logs FOR SELECT USING(company_id=app_company() AND (app_can('audit.view')));
CREATE POLICY audit_logs_write ON audit_logs FOR ALL USING(company_id=app_company() AND (false)) WITH CHECK(company_id=app_company() AND (false));
ALTER TABLE plan_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY plan_items_read ON plan_items FOR SELECT USING(company_id=app_company() AND (EXISTS(SELECT 1 FROM plans p WHERE p.id=plan_id)));
CREATE POLICY plan_items_write ON plan_items FOR ALL USING(company_id=app_company() AND (EXISTS(SELECT 1 FROM plans p WHERE p.id=plan_id AND p.representative_id=app_user() AND p.status IN ('draft','submitted')))) WITH CHECK(company_id=app_company() AND (EXISTS(SELECT 1 FROM plans p WHERE p.id=plan_id AND p.representative_id=app_user() AND p.status IN ('draft','submitted'))));
CREATE POLICY customers_create ON customers FOR INSERT WITH CHECK(company_id=app_company() AND created_by=app_user() AND app_area(area_id) AND app_can('customers.create'));
CREATE POLICY audit_insert ON audit_logs FOR INSERT WITH CHECK(company_id=app_company() AND user_id=app_user());
CREATE POLICY notification_insert ON notifications FOR INSERT WITH CHECK(company_id=app_company());
GRANT USAGE ON SCHEMA public TO fieldforce_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO fieldforce_app;
REVOKE ALL ON sessions,password_resets,login_attempts FROM fieldforce_app;
REVOKE INSERT,UPDATE,DELETE ON permissions,role_permissions FROM fieldforce_app;
REVOKE UPDATE,DELETE ON audit_logs,approval_actions,customer_assignments FROM fieldforce_app;
